const patterns={
 rock:{name:'Rock dasar · 4/4',meter:'4/4',steps:8,perBeat:2,labels:['1','&','2','&','3','&','4','&'],hh:seq(8),sn:[2,6],kick:[0,4],info:'Empat beat utama, delapan hi-hat. Snare di 2 dan 4; kick di 1 dan 3.',tip:'Mulai dengan hi-hat. Matikan snare dan kick, lalu aktifkan satu demi satu.'},
 extra:{name:'Rock · tambahan kick',meter:'4/4',steps:8,perBeat:2,labels:['1','&','2','&','3','&','4','&'],hh:seq(8),sn:[2,6],kick:[0,4,5],info:'Tambahkan kick pada & setelah 3. Waktu tangan tetap sama.',tip:'Dengarkan kick tambahan tanpa mempercepat hi-hat.'},
 ghost:{name:'Rock · ghost notes',meter:'4/4',steps:8,perBeat:2,labels:['1','&','2','&','3','&','4','&'],hh:seq(8),sn:[2,6],soft:[3,5],kick:[0,4],info:'Snare pelan pada & setelah 2 dan & setelah 3. Snare 2 dan 4 tetap jelas.',tip:'Ghost note adalah pukulan dalam slot ritme biasa dengan volume sangat pelan.'},
 quarters:{name:'Not 1/4 · empat pukulan',meter:'4/4',steps:4,perBeat:1,labels:['1','2','3','4'],sn:seq(4),info:'Satu pukulan per beat. Empat not 1/4 mengisi satu bar 4/4.',tip:'Ketuk kaki bersamaan dengan setiap snare.'},
 eighths:{name:'Not 1/8 · delapan pukulan',meter:'4/4',steps:8,perBeat:2,labels:['1','&','2','&','3','&','4','&'],sn:seq(8),stick:['R','L','R','L','R','L','R','L'],info:'Dua pukulan per beat. Delapan not 1/8 mengisi satu bar.',tip:'Ini delapan pukulan, tetapi tetap empat beat utama.'},
 singles:{name:'Single · not 1/16',meter:'4/4',steps:16,perBeat:4,labels:['1','e','&','a','2','e','&','a','3','e','&','a','4','e','&','a'],sn:seq(16),stick:Array(8).fill(['R','L']).flat(),info:'Empat not per beat, dengan tangan bergantian R L.',tip:'Ucapkan “satu e dan a, dua e dan a…”.'},
 doubles:{name:'Double · RR LL',meter:'4/4',steps:16,perBeat:4,labels:['1','e','&','a','2','e','&','a','3','e','&','a','4','e','&','a'],sn:seq(16),stick:Array(4).fill(['R','R','L','L']).flat(),info:'Dua pukulan terkontrol per tangan. Durasi not sama dengan single.',tip:'Audio menunjukkan ritmenya; R dan L tidak otomatis memiliki bunyi berbeda.'},
 para:{name:'Paradiddle · RLRR LRLL',meter:'4/4',steps:16,perBeat:4,labels:['1','e','&','a','2','e','&','a','3','e','&','a','4','e','&','a'],sn:seq(16),accent:[0,4,8,12],stick:Array(2).fill(['R','L','R','R','L','R','L','L']).flat(),info:'Single paradiddle: R L R R L R L L. Accent pada awal setiap kelompok empat.',tip:'Ratakan pukulan dahulu, lalu dengarkan perbedaan accent.'},
 rests:{name:'Rest · main dan diam',meter:'4/4',steps:4,perBeat:1,labels:['1','2','3','4'],sn:[0,2],info:'Main snare di 1 dan 3. Tanda istirahat satu beat di 2 dan 4.',tip:'Saat snare diam, beat dan metronom tetap berjalan.'},
 three:{name:'Birama 3/4',meter:'3/4',steps:3,perBeat:1,labels:['1','2','3'],sn:seq(3),accent:[0],info:'Tiga beat not 1/4 dalam satu bar. Setelah 3 kembali ke 1.',tip:'Ucapkan SATU dua tiga; rasakan pengulangannya.'},
 sixEight:{name:'Birama 6/8',meter:'6/8',steps:6,perBeat:3,labels:['1','2','3','4','5','6'],hh:seq(6),sn:[3],kick:[0],info:'Enam not 1/8 per bar; terasa dua beat besar: SATU-la-li DUA-la-li. Klik pada slot 1 dan 4.',tip:'BPM di sini menghitung beat not 1/4 bertitik, bukan keenam slot.'},
 triplet:{name:'Triplet · tiga per beat',meter:'4/4',steps:12,perBeat:3,labels:['1','trip','let','2','trip','let','3','trip','let','4','trip','let'],sn:seq(12),info:'Tiga not 1/8 triplet rata dalam satu beat 1/4. Empat kelompok per bar.',tip:'Bandingkan dengan not 1/8 biasa: dua per beat versus tiga per beat.'},
 sext:{name:'RllKRL · sextuplet',meter:'4/4',steps:24,perBeat:6,labels:Array.from({length:24},(_,i)=>i%6===0?String(i/6+1):String(i%6+1)),sn:[0,4,5,6,10,11,12,16,17,18,22,23],soft:[1,2,7,8,13,14,19,20],kick:[3,9,15,21],stick:Array(4).fill(['R','l','l','K','R','L']).flat(),info:'R l l K R L, enam slot per beat. Demo mengulang pola empat kali agar menjadi satu bar 4/4.',tip:'Kick ada di slot ke-4 tiap beat. Dua l tetap rata, bukan grace note. Huruf kecil bisa berbeda artinya di video lain.'},
 fill:{name:'Fill · snare dan tiga tom',meter:'4/4',steps:8,perBeat:2,labels:['1','&','2','&','3','&','4','&'],sn:[0,1],tom:[2,3],tom2:[4,5],floor:[6,7],stick:['R','L','R','L','R','L','R','L'],info:'Beat 1 snare; beat 2 Tom 1; beat 3 Tom 2; beat 4 Tom 3. Ritme tetap delapan not 1/8.',tip:'Pertahankan tempo saat memindahkan tangan ke tom.'}
};
const instruments={hh:'Hi-hat',sn:'Snare',kick:'Kick',tom:'Tom 1',tom2:'Tom 2',floor:'Tom 3'};
const chapters=[
['Kenali drum kit','Kick adalah suara rendah dari pedal kaki. Snare bersuara tajam. E-drum di app ini memiliki Tom 1 (tinggi), Tom 2 (sedang), dan Tom 3 (rendah/floor). Hi-hat terdiri dari dua cymbal yang dikontrol pedal. Ride menjaga pola; crash memberi penekanan. Setup umum memakai kaki kanan untuk kick dan kaki kiri untuk hi-hat. Klik diagram di atas untuk mendengar setiap bagian.'],
['Beat, bar, dan tempo','Beat adalah denyut dasar. Tempo menunjukkan seberapa cepat denyutnya, ditulis BPM (beats per minute). Dalam 4/4, satu bar berisi empat beat not 1/4. Pada 60 BPM, tiap beat berjarak satu detik. Subdivisi membagi satu beat menjadi bagian lebih kecil.','quarters'],
['4 ketukan atau 8 hitungan?','“8 hitungan” bisa berarti dua bar 4/4: hitung 1 sampai 8. Namun “8 pukulan” dapat berarti delapan not 1/8 dalam SATU bar 4/4: 1 & 2 & 3 & 4 &. Jumlah pukulan berbeda dari jumlah beat. Tanyakan konteksnya saat menonton video.','eighths'],
['Birama 4/4, 3/4, dan 6/8','Angka atas menyatakan jumlah unit not per bar. Angka bawah menyatakan nilai unit: 4 = not 1/4, 8 = not 1/8. 3/4 umumnya terasa tiga beat. 6/8 biasanya terasa dua beat besar, masing-masing berisi tiga not 1/8. Enam slot di 6/8 bukan sextuplet dalam satu beat 1/4.','sixEight'],
['Nilai not dan cara menghitung','Saat not 1/4 menjadi satu beat: not penuh = 4 beat, not 1/2 = 2, not 1/4 = 1, not 1/8 = 1/2, not 1/16 = 1/4. Ucapkan eighth “1 dan 2 dan”. Sixteenth “1 e dan a”. Kepala kosong tanpa tangkai = not penuh; kepala kosong bertangkai = not 1/2; kepala isi bertangkai = not 1/4. Satu bendera/balok = 1/8, dua = 1/16.','singles'],
['Peta staff dan simbol','Staff terdiri dari lima garis. Clef perkusi di kiri berbentuk dua garis tebal. Posisi not menentukan instrumen, bukan melodi. Stem adalah tangkai; beam adalah balok penghubung. Not yang sejajar vertikal dimainkan bersamaan. Bar line membatasi bar. Peta instrumen bisa berbeda di buku lain; selalu periksa legend.'],
['Rest, titik, dan tuplet','Rest berarti diam selama nilai tertulis; hitungan tetap berjalan. Titik setelah not menambah separuh nilainya: not 1/4 bertitik = 1,5 beat not 1/4. Angka kecil 3 menandai triplet; angka 6 menandai sextuplet. Tiga not 1/8 triplet atau enam not 1/16 sextuplet sama-sama dapat mengisi satu beat 1/4.','rests'],
['Kamus istilah','Groove: pola berulang yang mendukung lagu. Fill: perubahan singkat menuju bagian baru atau kembali ke groove. Rudiment: pola dasar sticking. Chops: sebutan kemampuan atau pola atraktif, bukan satu rudiment. Accent (>): not lebih keras dari sekitarnya. Ghost note (kepala not dalam kurung): sangat pelan. Dynamics: keras-lembut; p = pelan, mf = sedang, f = keras. Crescendo makin keras; decrescendo makin pelan. Roll: bunyi berkelanjutan dari pukulan berulang. Double-stroke roll memakai RR LL; buzz roll memakai beberapa pantulan per tangan.'],
['Groove rock dan variasi','Hi-hat memainkan setiap eighth; snare di 2 dan 4; kick di 1 dan 3. Mulai dari hi-hat saja. Tambahkan kick lalu snare. Variasi sederhana menambah kick pada & setelah 3. Tangan tetap menjaga waktu yang sama.','extra'],
['Sticking dan paradiddle','R = tangan kanan, L = tangan kiri, K = kaki kick. Single stroke: R L R L. Double stroke: R R L L. Single paradiddle: R L R R L R L L. Setiap huruf menunjukkan satu pukulan, tetapi tidak menentukan nilai notnya; periksa notasi dan hitungan. Latih perlahan 40–60 BPM.','para'],
['Ghost note, flam, dan drag','Ghost note adalah pukulan sangat pelan dalam slot ritme biasa. Flam memiliki satu grace note kecil tepat sebelum pukulan utama. Drag memiliki dua grace note kecil sebelum not utama. Grace note tidak menjadi subdivisi tambahan yang dihitung rata seperti sextuplet. Pada flam, mainkan satu stik rendah dan yang lain lebih tinggi. Jaga jarak kedua bunyi dekat.','ghost'],
['Sextuplet RllKRL','Baca R l l K R L: kanan, kiri pelan, kiri pelan, kick, kanan, kiri. Keenam slot rata dalam satu beat 1/4; kick pada slot ke-4. Huruf kecil bukan aturan universal, jadi cek legend pembuat video. Mulai dengan semua volume sama, baru pelankan dua kiri. Demo mengulang pola selama empat beat, bukan hanya sekali.','sext'],
['Fill yang kembali tepat waktu','Mainkan delapan not 1/8: R L R L R L R L. Coba dua pukulan snare, dua Tom 1, dua Tom 2, dan dua Tom 3. Latihan tiga bar groove dan satu bar fill. Pada 1 berikutnya, masuk kick + crash lalu kembali ke groove. Untuk fill RllKRL satu beat: groove pada 1, 2, 3; pola enam not pada beat 4.','fill'],
['Mendengar lagu lalu mencatat','Ini disebut transkripsi. Loop satu bar sederhana. Ketuk kaki untuk mencari beat, lalu cari tempat pola kembali ke 1. Dengarkan snare dahulu, kemudian kick dan hi-hat. Gunakan kotak eighth; ubah ke sixteenth jika perlu. Jika terdengar kelompok tiga, coba triplet. Uji catatan dengan memainkan bersama lagu. Audio tidak selalu menunjukkan sticking R/L; pola yang sama bisa dimainkan dengan tangan berbeda.'],
['Dari kotak ke notasi','Pada pola rock: hi-hat ada di semua kolom 1 & 2 & 3 & 4 &; snare di kolom 2 dan 4; kick di 1 dan 3. Setiap kolom adalah waktu yang sama. Catat dahulu instrumen per kolom, lalu pindahkan ke staff. Matikan instrumen di lab untuk melatih mendengar lapisan satu per satu.','rock'],
['Rencana latihan 20 menit','3 menit: pemanasan single dan double. 4 menit: menghitung dan membaca, termasuk rest. 5 menit: groove. 4 menit: paradiddle atau RllKRL bergantian hari. 4 menit: tiga bar groove + satu bar fill. Minggu 1 fokus hitungan dan groove; minggu 2 rest dan double; minggu 3 paradiddle dan fill; minggu 4 ghost note dan sextuplet. Naikkan 5 BPM setelah empat bar rapi. Turunkan tempo jika kontrol memburuk. Berhenti bila sakit; gunakan pelindung pendengaran pada drum akustik.']
];
let ctx,master,soundSystem,synthEngine,running=false,timer=null,nextTime=0,step=0,bars=0,generation=0,raf=null,pending=[],selected='rock';const enabled={hh:true,sn:true,kick:true,tom:true,tom2:true,floor:true};
function initAudio(){if(ctx)return;const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw new Error('Browser ini belum mendukung audio. Coba Chrome atau Edge terbaru.');ctx=new Audio();master=ctx.createGain();master.gain.value=+$('#volume').value;master.connect(ctx.destination);synthEngine=createDrumSynth(ctx,master);soundSystem=DrumSound.create(ctx,master);}


function hit(inst,t,v=1){if(inst==='click'){synthEngine.play(inst,t,v);return;}if(!soundSystem.play(inst,t,v))synthEngine.play(inst,t,v);}
function events(p,i){const a=[];for(const k of Object.keys(instruments))if((p[k]||[]).includes(i))a.push([k,(p.accent||[]).includes(i)?1:.72]);if((p.soft||[]).includes(i))a.push(['sn',.18]);return a;}
function bpm(){const v=Number($('#bpm').value);return Number.isFinite(v)?Math.max(30,Math.min(180,v||65)):65;}
function schedule(){if(!running)return;const p=patterns[selected];while(nextTime<ctx.currentTime+.10){const i=step;for(const [k,v] of events(p,i))if(enabled[k]&&$('#drumSound').checked)hit(k,nextTime,v);if($('#click').checked&&i%p.perBeat===0)hit('click',nextTime,i===0?2:1);pending.push({i,t:nextTime,bar:bars+1});nextTime+=60/bpm()/p.perBeat;step=(step+1)%p.steps;if(step===0)bars++;}timer=setTimeout(schedule,25);}
function paint(){if(!running)return;let e;while(pending.length&&pending[0].t<=ctx.currentTime)e=pending.shift();if(e){const p=patterns[selected];document.querySelectorAll('[data-step]').forEach(n=>n.classList.toggle('current',+n.dataset.step===e.i));const b=Math.floor((e.i%(p.barSteps||(p.meter==='6/8'?6:p.perBeat*Number(p.meter.split('/')[0]))))/p.perBeat)+1;$('#counter').classList.remove('idle');$('#counter').textContent=String(b);$('#subcount').textContent=(p.stick?p.stick[e.i]+' · ':'')+(p.meter==='6/8'?'Slot '+p.labels[e.i]+' / 6':p.perBeat===6?'Slot '+(e.i%6+1)+' / 6':p.perBeat===1?'Ketukan utama':p.labels[e.i]);document.querySelectorAll('.pulse').forEach((n,i)=>n.classList.toggle('active',i===b-1));$('#bar').textContent='Bar '+e.bar;updateDock(e.i,e.bar);const line=$('#playhead');if(line){const x=typeof scorePosition==='function'?scorePosition(p,e.i):92+e.i*(710/p.steps);line.setAttribute('x1',x);line.setAttribute('x2',x);}document.querySelectorAll('.pad').forEach(n=>n.classList.toggle('flash',events(p,e.i).some(([k])=>k===n.dataset.inst&&enabled[k])));}raf=requestAnimationFrame(paint);}
async function play(){if(typeof recording!=='undefined'&&recording){status('#recordStatus','Selesaikan rekaman sebelum memainkan pola.',true);return;}if(running){stop();return;}const token=++generation;try{initAudio();await ctx.resume();await soundSystem.ready;if(token!==generation)return;running=true;step=0;bars=0;pending=[];nextTime=ctx.currentTime+.08;master.gain.setValueAtTime(+$('#volume').value,ctx.currentTime);$('#play').textContent='Jeda';$('#trackState').textContent='Sedang dimainkan · ulang otomatis';$('#status').textContent='Demo sedang dimainkan.';schedule();paint();}catch(e){$('#status').textContent=e.message;$('#counter').textContent=e.message;}}
function stop(){generation++;running=false;clearTimeout(timer);cancelAnimationFrame(raf);pending=[];if(master)master.gain.setValueAtTime(0,ctx.currentTime);if(soundSystem)soundSystem.stop();if(synthEngine)synthEngine.stop();$('#play').textContent='Mainkan';$('#trackState').textContent='Siap / dijeda';$('#status').textContent='Demo dihentikan.';document.querySelectorAll('.current,.flash').forEach(n=>n.classList.remove('current','flash'));}
function choose(key){stop();selected=key;$('#pattern').value=key;step=0;bars=0;$('#bar').textContent='Bar 1';$('#counter').textContent='Siap latihan?';$('#counter').classList.add('idle');$('#subcount').textContent='Ikuti hitungan, jaga tangan tetap rileks.';render();}
function render(){const p=patterns[selected];updateDock(-1,1);$('#pulses').innerHTML=Array.from({length:p.steps/p.perBeat},()=>'<span class="pulse"></span>').join('');$('#explain').textContent=p.info;$('#tip').textContent=p.tip;$('#meter').textContent='Birama '+p.meter;$('#timing').textContent=p.meter==='6/8'?'1 klik = not 1/4 bertitik':'1 klik = not 1/4';const grid=$('#grid');grid.innerHTML='';grid.style.gridTemplateColumns=`105px repeat(${p.steps}, minmax(29px, 1fr))`;grid.style.minWidth=Math.max(650,105+p.steps*34)+'px';
 const add=(label,values,type)=>{const name=document.createElement('div');name.className='cell label';if(type&&type!=='stick'){const l=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=enabled[type];check.setAttribute('aria-label','Bunyikan '+label);check.addEventListener('change',()=>enabled[type]=check.checked);l.append(check,document.createTextNode(label));name.append(l);}else name.textContent=label;grid.append(name);values.forEach((v,i)=>{const d=document.createElement('div');d.className='cell'+(v==='●'?' hit':v==='(●)'?' soft':'')+(type===null&&i%p.perBeat===0?' beat':'');d.dataset.step=i;d.textContent=v;grid.append(d);});};
 add('Hitungan',p.labels,null);for(const [k,l]of Object.entries(instruments))if(p[k]||k==='sn'&&p.soft)add(l,seq(p.steps).map(i=>(k==='sn'&&(p.soft||[]).includes(i))?'(●)':(p[k]||[]).includes(i)?'●':'–'),k);if(p.stick)add('Sticking',p.stick,'stick');notation(p);}
function notation(p){const W=850,H=180,y=104,dx=710/p.steps,x=i=>92+i*dx;let s=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Notasi ${p.name}"><g stroke="#193442" fill="none" stroke-width="1">`;for(let j=0;j<5;j++)s+=`<path d="M25 ${y-j*8}H820"/>`;s+=`<path stroke-width="3" d="M35 78V96M41 78V96"/><path d="M820 72V104"/></g><g font-family="system-ui" font-size="15" fill="#193442"><text x="55" y="84">${p.meter.split('/')[0]}</text><text x="55" y="103">${p.meter.split('/')[1]}</text></g>`;
 const yy={kick:y,sn:y-20,hh:y-40,tom:y-28,tom2:y-24,floor:y-8};for(let i=0;i<p.steps;i++){const ev=events(p,i),xx=x(i);if(ev.length){for(const [k,v]of ev){if(k==='hh')s+=`<path d="M${xx-3} ${yy[k]-3}l6 6m-6 0l6 -6" stroke="#193442"/>`;else s+=`<ellipse cx="${xx}" cy="${yy[k]}" rx="3.7" ry="2.6" fill="#193442" transform="rotate(-18 ${xx} ${yy[k]})"/>`;if(v<.3)s+=`<text x="${xx-10}" y="${yy[k]+4}" font-size="13" fill="#193442">(</text><text x="${xx+6}" y="${yy[k]+4}" font-size="13" fill="#193442">)</text>`;}s+=`<path d="M${xx+3} ${Math.max(...ev.map(([k])=>yy[k]))}V40" stroke="#193442"/>`;if((p.accent||[]).includes(i))s+=`<text x="${xx-4}" y="27" fill="#193442" font-size="16">&gt;</text>`;}else s+=`<path d="M${xx-3} 76l6 7-6 7 6 6q-12-2-5 9" stroke="#193442" fill="none" stroke-width="2"/>`;s+=`<text x="${xx}" y="137" text-anchor="middle" font-size="${p.steps>16?11:13}" fill="#193442">${p.labels[i]}</text>`;if(p.stick)s+=`<text x="${xx}" y="160" text-anchor="middle" font-size="12" fill="#193442">${p.stick[i]}</text>`;}
 if(p.perBeat>1)for(let i=0;i<p.steps;i+=p.perBeat){const n=p.perBeat;const levels=n===4||n===6?2:1;for(let l=0;l<levels;l++)s+=`<path d="M${x(i)+3} ${40+l*5}H${x(i+n-1)+3}" stroke="#193442" stroke-width="3"/>`;if(n===3&&p.meter!=='6/8'||n===6)s+=`<text x="${(x(i)+x(i+n-1))/2}" y="26" text-anchor="middle" font-size="13" fill="#193442">${n}</text>`;}
 s+='<line id="playhead" x1="92" x2="92" y1="32" y2="118" stroke="#ce662c" stroke-width="2" opacity=".75"/></svg>';$('#notation').innerHTML=s;}
for(const [k,p]of Object.entries(patterns)){const o=document.createElement('option');o.value=k;o.textContent=p.name;$('#pattern').append(o);}
$('#pattern').addEventListener('change',e=>choose(e.target.value));$('#play').addEventListener('click',play);$('#reset').addEventListener('click',()=>{const was=running;choose(selected);if(was)play();});$('#bpm').addEventListener('change',()=>$('#bpm').value=bpm());$('#volume').addEventListener('input',()=>{if(master&&running)master.gain.setTargetAtTime(+$('#volume').value,ctx.currentTime,.01);});
document.querySelectorAll('[data-demo]').forEach(b=>b.addEventListener('click',()=>{choose(b.dataset.demo);play();}));
const pads=[['crash','Crash',19,15,'cym'],['ride','Ride',80,15,'cym'],['tom','Tom 1',38,32,''],['tom2','Tom 2',63,32,''],['floor','Tom 3',82,64,''],['sn','Snare',40,66,''],['hh','Hi-hat',14,60,'cym'],['kick','Kick',60,91,'']];
for(const [k,l,x,y,cl]of pads){const b=document.createElement('button');b.className='pad '+cl;b.dataset.inst=k;b.style.left=x+'%';b.style.top=y+'%';b.textContent=l;b.setAttribute('aria-label','Dengarkan '+l);b.addEventListener('click',async()=>{try{stop();initAudio();await ctx.resume();await soundSystem.ready;master.gain.value=+$('#volume').value;hit(k,ctx.currentTime+.01);$('#kitinfo').textContent=l+' · '+soundSystem.label;b.classList.add('flash');setTimeout(()=>b.classList.remove('flash'),180);}catch(e){$('#kitinfo').textContent=e.message;}});$('#kit').append(b);}
chapters.forEach(([t,body,demo],i)=>{const d=document.createElement('details');d.id='bab'+i;if(i===0)d.open=true;const s=document.createElement('summary');s.textContent=t;const p=document.createElement('p');p.textContent=body;d.append(s,p);if(demo){const b=document.createElement('button');b.textContent='Coba demo bab ini';b.addEventListener('click',()=>{choose(demo);play();});d.append(b);}$('#lessons').append(d);const a=document.createElement('a');a.href='#'+d.id;a.textContent=t;a.addEventListener('click',()=>d.open=true);$('#toc').append(a);});
document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>$('#feedback').textContent=b.dataset.answer==='right'?'Betul! Ada empat beat utama, masing-masing berisi dua not 1/8.':'Coba lagi. Kelompokkan delapan pukulan menjadi pasangan: 1 &, 2 &, 3 &, 4 &.'));
document.addEventListener('visibilitychange',()=>{if(document.hidden&&running){stop();$('#counter').classList.add('idle');$('#counter').textContent='Dijeda';$('#subcount').textContent='Tekan Mainkan saat kembali.';}});render();

