$('#sidebarChapters').append($('#toc'));
function setMode(mode){const focus=mode==='focus';document.body.classList.toggle('mode-focus',focus);document.body.classList.toggle('mode-full',!focus);$('#focusMode').setAttribute('aria-pressed',String(focus));$('#fullMode').setAttribute('aria-pressed',String(!focus));closeSidebar();try{localStorage.setItem('drum-view',mode);}catch{}}
function closeSidebar(){$('#sidebar').classList.remove('open');$('#openSidebar').setAttribute('aria-expanded','false');}
$('#focusMode').addEventListener('click',()=>{setMode('focus');window.scrollTo(0,0);});$('#fullMode').addEventListener('click',()=>setMode('full'));
$('#openSidebar').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#openSidebar').setAttribute('aria-expanded','true');});$('#closeSidebar').addEventListener('click',closeSidebar);
$('#practiceLink').addEventListener('click',closeSidebar);
document.querySelectorAll('.toc a').forEach(a=>a.addEventListener('click',()=>{setMode('full');document.querySelectorAll('.toc a').forEach(n=>n.classList.remove('active'));a.classList.add('active');closeSidebar();}));
function adjustTempo(delta){if($('#bpm').disabled)return;$('#bpm').value=Math.max(30,Math.min(180,bpm()+delta));}
$('#slower').addEventListener('click',()=>adjustTempo(-5));$('#faster').addEventListener('click',()=>adjustTempo(5));
document.addEventListener('keydown',e=>{if(e.code==='Escape'){closeSidebar();return;}if(e.altKey||e.ctrlKey||e.metaKey||e.repeat||e.target.isContentEditable||['INPUT','SELECT','TEXTAREA','BUTTON','SUMMARY','A'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();play();}else if(e.code==='ArrowLeft'){e.preventDefault();adjustTempo(-5);}else if(e.code==='ArrowRight'){e.preventDefault();adjustTempo(5);}else if(e.code==='KeyR'){e.preventDefault();$('#reset').click();}});
try{if(localStorage.getItem('drum-view')==='focus')setMode('focus');}catch{}
// Deep links to chapters always open the reading view.
if(location.hash.startsWith('#bab')){setMode('full');const chapter=document.querySelector(location.hash);if(chapter){chapter.open=true;requestAnimationFrame(()=>chapter.scrollIntoView());}}


// Move the existing controls into one player; no duplicate audio engine or IDs.
$('#trackSelect').prepend($('#pattern').parentElement);
$('#playerCenter').prepend(document.querySelector('.transport'));
$('#playerOptions').append(document.querySelector('.tempo-controls'));
const originalSettings=document.querySelector('#lab .settings');
const volumeLabel=$('#volume').parentElement;
$('#playerOptions').append(volumeLabel);
while(originalSettings.firstChild)$('#dockSettings').append(originalSettings.firstChild);
originalSettings.remove();
// Show the same volume control in the dock at every screen size.
volumeLabel.classList.add('volume-label');
$('#dockSettings').append(volumeLabel);

function updateDock(index,bar){const p=patterns[selected];const beat=index<0?'—':Math.floor(index/p.perBeat)+1;$('#miniCount').textContent='Beat '+beat;$('#miniBar').textContent='Bar '+bar;const percent=index<0?0:(index+1)/p.steps*100;$('#loopFill').style.width=percent+'%';$('#loopProgress').setAttribute('aria-valuenow',String(Math.round(percent)));updateScore(index,bar);}
updateDock(-1,1);
// Reserve the actual dock height so no lesson can disappear behind the player.
if(typeof ResizeObserver!=='undefined')new ResizeObserver(entries=>{document.documentElement.style.setProperty('--player-height',($('#playerDock').dataset.size==='full'?0:Math.ceil(entries[0].target.getBoundingClientRect().height))+'px');}).observe($('#playerDock'));


// The notation itself lives in the persistent player, like karaoke lyrics.
$('#scoreViewport').append($('#notation'));
const scoreHelp=document.createElement('p');scoreHelp.id='scoreHelp';scoreHelp.textContent='Notasi live ada di player bawah. Pilih Setengah atau Penuh untuk mengikutinya saat latihan.';
const oldNotationHeading=Array.from(document.querySelectorAll('#lab h3')).find(n=>n.textContent.includes('Notasi'));
if(oldNotationHeading)oldNotationHeading.replaceWith(scoreHelp);
for(const selector of ['#playerDock > .player-track','#playerDock > .player-center','#playerDock > .player-options']){const part=document.querySelector(selector);if(part)$('#scoreFooter').append(part);}
function setPlayerSize(size){if(!['mini','half','full'].includes(size))return;$('#playerDock').dataset.size=size;document.body.classList.toggle('score-expanded',size==='full');document.querySelectorAll('[data-size-button]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sizeButton===size)));$('#scoreModeLabel').textContent=size==='mini'?'Player ringkas':'Ikuti pukulannya';try{localStorage.setItem('drum-player-size',size);}catch{}}
function updateScore(index,bar){const p=patterns[selected];$('#scoreBar').textContent='Bar '+bar;$('#scoreBeat').textContent=index<0?'Siap latihan':'Beat '+(Math.floor(index/p.perBeat)+1);$('#scoreSticking').textContent=index<0?p.name:(p.stick?'Sticking '+p.stick[index]+' · ':'')+(p.perBeat>1?'Slot '+(index%p.perBeat+1)+' / '+p.perBeat:p.labels[index]);
 if(index>=0&&$('#playerDock').dataset.size!=='mini'){const view=$('#scoreViewport'),note=$('#notation');if(view.clientWidth&&note.scrollWidth>view.clientWidth){const target=(92+index*710/p.steps)/850*note.scrollWidth;view.scrollLeft=Math.max(0,target-view.clientWidth*.35);}}
}
document.querySelectorAll('[data-size-button]').forEach(b=>b.addEventListener('click',()=>setPlayerSize(b.dataset.sizeButton)));
document.addEventListener('keydown',e=>{if(e.code==='Escape'&&$('#playerDock').dataset.size==='full')setPlayerSize('half');});
try{setPlayerSize(localStorage.getItem('drum-player-size')||'half');}catch{setPlayerSize('half');}
updateScore(-1,1);

// Local studio: user-authored patterns, Web MIDI, study tools and draft analysis.
const STORE='drum-companion-v2';
const partNames=DRUM_PARTS;
Object.assign(instruments,{ride:'Ride',crash:'Crash'});
enabled.ride=true;enabled.crash=true;
let appData={patterns:[],mapping:{},sessions:[]},storageOK=true;



function loadApp(){try{const d=JSON.parse(localStorage.getItem(STORE)||'null');if(d&&typeof d==='object'){if(Array.isArray(d.patterns))appData.patterns=d.patterns.slice(0,100).flatMap(item=>{try{return [{id:safeText(item.id,60),bpm:Math.max(30,Math.min(180,+item.bpm||65)),pattern:cleanPattern(item.pattern)}];}catch{return [];}});if(d.mapping&&typeof d.mapping==='object')for(const [note,inst]of Object.entries(d.mapping))if(/^\d+$/.test(note)&&+note<=127&&partNames[inst])appData.mapping[note]=inst;if(Array.isArray(d.sessions))appData.sessions=d.sessions.slice(0,100).filter(x=>x&&Number.isFinite(x.seconds)&&x.seconds>0&&Number.isFinite(x.date)).map(x=>({name:safeText(x.name),seconds:Math.min(3600,x.seconds),bpm:Math.max(30,Math.min(180,+x.bpm||65)),date:x.date}));}}catch{storageOK=false;}}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(appData));return true;}catch{storageOK=false;return false;}}
function status(id,message,error=false){$(id).textContent=message;$(id).classList.toggle('error',error);}
function uid(){return Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,8);}
function installPattern(key,p,tempo){patterns[key]=p;let option=Array.from($('#pattern').options).find(o=>o.value===key);if(!option){option=document.createElement('option');option.value=key;$('#pattern').append(option);}option.textContent=p.name;if(tempo)$('#bpm').value=tempo;}
function showTool(key,scroll=false){
 const allowed=['editor','midi','library','youtube','audio','session','sound'];if(!allowed.includes(key))return;
 if($('#playerDock').dataset.size==='full')setPlayerSize('half');setMode('full');
 for(const name of allowed){$('#tool-'+name).hidden=name!==key;$('#tab-'+name).setAttribute('aria-selected',String(name===key));$('#tab-'+name).tabIndex=name===key?0:-1;}
 if(key==='library')renderLibrary();closeSidebar();if(scroll)$('#workspace').scrollIntoView({block:'start'});
}
document.querySelectorAll('[data-tool]').forEach(b=>b.addEventListener('click',()=>showTool(b.dataset.tool)));
document.querySelector('.tool-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const keys=['editor','midi','library','youtube','audio','session','sound'],index=keys.indexOf(e.target.dataset.tool);if(index<0)return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?keys.length-1:(index+(e.key==='ArrowRight'?1:-1)+keys.length)%keys.length;showTool(keys[next]);$('#tab-'+keys[next]).focus();});
const toolsNav=document.createElement('div');toolsNav.className='app-links';for(const [key,label]of [['editor','Buat pola'],['midi','MIDI recorder'],['library','Cari lagu & koleksi'],['youtube','YouTube study'],['audio','Audio ke draf'],['session','Latihan harian']]){const a=document.createElement('a');a.href='#workspace';a.textContent=label;a.addEventListener('click',()=>showTool(key,true));toolsNav.append(a);}$('#sidebarChapters').before(toolsNav);

// Event precision and dynamics are retained for user recordings.
const bookEvents=events;
events=function(p,i){if(!p.velocities)return bookEvents(p,i);const a=[];for(const k of Object.keys(partNames))if((p[k]||[]).includes(i))a.push([k,p.velocities[k+':'+i]??.75]);return a;};
const scoreLayout=p=>({width:Math.max(850,140+p.steps*36),dx:Math.max(710,p.steps*36)/p.steps});
function scorePosition(p,i){return 92+i*scoreLayout(p).dx;}
// A complete voice of equal subdivisions, with correct rests and bar boundaries.
notation=function(p){
 const layout=scoreLayout(p),W=layout.width,y=104,barSteps=p.barSteps||(p.meter==='6/8'?6:p.perBeat*Number(p.meter.split('/')[0]));
 let s=`<svg viewBox="0 0 ${W} 180" role="img" aria-label="Notasi drum ${safeText(p.name).replace(/[&<>\"]/g,'')}" xmlns="http://www.w3.org/2000/svg"><g stroke="#193442" fill="none" stroke-width="1">`;
 for(let j=0;j<5;j++)s+=`<path d="M25 ${y-j*8}H${W-18}"/>`;
 s+=`<path stroke-width="3" d="M35 78V96M41 78V96"/><path d="M${W-18} 72V104"/></g><g font-family="system-ui" font-size="15" fill="#193442"><text x="55" y="84">${p.meter.split('/')[0]}</text><text x="55" y="103">${p.meter.split('/')[1]}</text></g>`;
 const yy=STAFF_POSITIONS,levels=p.perBeat===4||p.perBeat===6?2:p.perBeat===1?0:1;
 for(let i=0;i<p.steps;i++){
  const ev=events(p,i),x=scorePosition(p,i);
  if(i>0&&i%barSteps===0)s+=`<path d="M${x-layout.dx*.5} 72V104" stroke="#193442"/><text x="${x-5}" y="16" font-size="10" fill="#6c8175">Bar ${i/barSteps+1}</text>`;
  if(ev.length){for(const [k,v]of ev){const cy=yy[k]??88;if(['hh','ride','crash'].includes(k))s+=`<path d="M${x-3} ${cy-3}l6 6m-6 0l6 -6" stroke="#193442"/>`;else s+=`<ellipse cx="${x}" cy="${cy}" rx="3.7" ry="2.6" fill="#193442" transform="rotate(-18 ${x} ${cy})"/>`;if(k==='crash')s+=`<path d="M${x-7} 56h14" stroke="#193442"/>`;if(v<.35)s+=`<text x="${x-10}" y="${cy+4}" font-size="13" fill="#193442">(</text><text x="${x+6}" y="${cy+4}" font-size="13" fill="#193442">)</text>`;}s+=`<path d="M${x+3} ${Math.max(...ev.map(([k])=>yy[k]??88))}V40" stroke="#193442"/>`;if((p.accent||[]).includes(i))s+=`<text x="${x-4}" y="27" fill="#193442" font-size="16">&gt;</text>`;
  }else if(levels===0)s+=`<path d="M${x-3} 76l6 7-6 7 6 6q-12-2-5 9" stroke="#193442" fill="none" stroke-width="2"/>`;
  else{ s+=`<path d="M${x+4} 78l-7 24" stroke="#193442" stroke-width="1.6"/><circle cx="${x-2}" cy="83" r="2.8" fill="#193442"/><path d="M${x-2} 83l6 -5" stroke="#193442"/>`;if(levels===2)s+=`<circle cx="${x-5}" cy="92" r="2.8" fill="#193442"/><path d="M${x-5} 92l6 -5" stroke="#193442"/>`;}
  s+=`<text x="${x}" y="137" text-anchor="middle" font-size="12" fill="#193442">${p.labels[i]}</text>`;if(p.stick)s+=`<text x="${x}" y="160" text-anchor="middle" font-size="12" fill="#193442">${p.stick[i]}</text>`;
 }
 if(levels)for(let start=0;start<p.steps;start+=p.perBeat){
  // Beam only consecutive sounded notes; single notes receive flags.
  let run=[];const finish=()=>{if(run.length>1)for(let l=0;l<levels;l++)s+=`<path d="M${scorePosition(p,run[0])+3} ${40+l*5}H${scorePosition(p,run[run.length-1])+3}" stroke="#193442" stroke-width="3"/>`;else if(run.length===1)for(let l=0;l<levels;l++){const x=scorePosition(p,run[0])+3;s+=`<path d="M${x} ${40+l*5}q10 5 6 14" stroke="#193442" fill="none" stroke-width="1.7"/>`;}run=[];};
  for(let j=start;j<Math.min(start+p.perBeat,p.steps);j++){if(events(p,j).length)run.push(j);else finish();}finish();
  if(p.perBeat===3&&p.meter!=='6/8'||p.perBeat===6){const a=scorePosition(p,start),b=scorePosition(p,Math.min(start+p.perBeat-1,p.steps-1));s+=`<path d="M${a} 28v-4H${b}v4" stroke="#8ba094" fill="none"/><rect x="${(a+b)/2-7}" y="16" width="14" height="13" fill="#eff4f1"/><text x="${(a+b)/2}" y="26" text-anchor="middle" font-size="12" fill="#193442">${p.perBeat}</text>`;}
 }
 s+='<line id="playhead" x1="92" x2="92" y1="32" y2="118" stroke="#ce662c" stroke-width="2" opacity=".8"/></svg>';
 $('#notation').innerHTML=s;$('#notation').style.minWidth=W+'px';
};
const originalUpdateScore=updateScore;
updateScore=function(index,bar){
 originalUpdateScore(index,bar);const p=patterns[selected],barSteps=p.barSteps||(p.meter==='6/8'?6:p.perBeat*Number(p.meter.split('/')[0]));
 if(index>=0){const localBeat=Math.floor((index%barSteps)/p.perBeat)+1;$('#scoreBeat').textContent='Beat '+localBeat;$('#miniCount').textContent='Beat '+localBeat;$('#scoreBar').textContent='Bar '+(Math.floor(index/barSteps)+1)+(p.steps>barSteps?' / '+Math.ceil(p.steps/barSteps):'');}
 const view=$('#scoreViewport'),note=$('#notation');if(index>=0&&view.clientWidth&&$('#playerDock').dataset.size!=='mini'){const target=scorePosition(p,index)/scoreLayout(p).width*note.scrollWidth;view.scrollLeft=Math.max(0,target-view.clientWidth*.35);}
};

let draft=cleanPattern({name:'Pola pertamaku',meter:'4/4',steps:16,perBeat:4});
function draftFromUI(){const q=+$('#editGrid').value,b=+$('#editBars').value;return cleanPattern({name:$('#draftTitle').value,meter:'4/4',steps:q*4*b,perBeat:q});}
function loadDraft(p,title){draft=cleanPattern(p);if(title)draft.name=safeText(title);$('#draftTitle').value=draft.name;$('#editGrid').value=String(draft.perBeat);$('#editBars').value=String(draft.steps/draft.barSteps);drawEditor();}
function syncDraftName(){draft.name=safeText($('#draftTitle').value)||'Pola tanpa judul';}
function drawEditor(){
 const host=$('#editorGrid');host.replaceChildren();
 const row=(label,k)=>{const r=document.createElement('div');r.className='edit-row';r.style.gridTemplateColumns=`85px repeat(${draft.steps},32px)`;r.style.minWidth=85+draft.steps*36+'px';const name=document.createElement('div');name.className='edit-label';name.textContent=label;r.append(name);
  for(let i=0;i<draft.steps;i++){const n=document.createElement(k?'button':'div');const has=k&&(draft[k]||[]).includes(i),v=draft.velocities[k+':'+i]??.75;n.className=(k?'edit-slot':'edit-count')+(has?(v<.35?' ghost':' on'):'')+(i%draft.barSteps===0?' bar-start':'');n.textContent=k?(has?(v<.35?'(●)':'●'):'·'):draft.labels[i];if(k){n.type='button';n.setAttribute('aria-label',`${label}, bar ${Math.floor(i/draft.barSteps)+1}, beat ${Math.floor(i%draft.barSteps/draft.perBeat)+1}, slot ${i%draft.perBeat+1}, ${has?v<.35?'pelan':'bunyi':'diam'}`);n.setAttribute('aria-pressed',String(!!has));n.addEventListener('click',()=>{if(!has){draft[k].push(i);draft.velocities[k+':'+i]=.75;}else if(v>=.35)draft.velocities[k+':'+i]=.2;else{draft[k]=draft[k].filter(j=>j!==i);delete draft.velocities[k+':'+i];}drawEditor();status('#editorStatus','Draf berubah. Tekan Dengarkan draf untuk memeriksa hasilnya.');});}r.append(n);}host.append(r);
 };row('Hitungan',null);for(const [k,name]of Object.entries(partNames))row(name,k);
}
function activateDraft(start=false){syncDraftName();installPattern('draft',cleanPattern(draft));choose('draft');if(start)play();}
$('#blankDraft').addEventListener('click',()=>{draft=draftFromUI();drawEditor();status('#editorStatus','Pola kosong dibuat. Klik kotak untuk menambah not.');});
$('#copyCurrent').addEventListener('click',()=>{const p=patterns[selected];if(p.meter!=='4/4'){status('#editorStatus','Editor ini memakai 4/4. Untuk 6/8, gunakan pola bawaan di player.',true);return;}const copy={...p,velocities:{...p.velocities},soft:undefined};for(const k of Object.keys(partNames))copy[k]=[...(p[k]||[])];for(let i=0;i<p.steps;i++)for(const [k,v]of events(p,i)){if(!copy[k].includes(i))copy[k].push(i);copy.velocities[k+':'+i]=v;}loadDraft(copy,p.name+' · salinan');status('#editorStatus','Pola player disalin. Rekaman yang belum disimpan dapat diedit di sini.');});
$('#previewDraft').addEventListener('click',()=>activateDraft(true));
$('#saveDraft').addEventListener('click',()=>{if(appData.patterns.length>=100){status('#editorStatus','Koleksi penuh (100 pola). Ekspor cadangan dan hapus pola yang tidak diperlukan.',true);return;}syncDraftName();const item={id:uid(),bpm:bpm(),pattern:cleanPattern(draft)};appData.patterns.unshift(item);const saved=persist();installPattern('saved_'+item.id,item.pattern);status('#editorStatus',saved?'Pola tersimpan. Temukan di Cari lagu & koleksi.':'Pola ada dalam sesi ini, tetapi browser gagal menyimpan. Ekspor JSON untuk cadangan.',!saved);renderLibrary();});
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function filename(){return (safeText($('#draftTitle').value).replace(/[^\p{L}\p{N}_-]+/gu,'-').slice(0,60)||'pola-drum');}
$('#exportJson').addEventListener('click',()=>{syncDraftName();download(new Blob([JSON.stringify({version:2,bpm:bpm(),pattern:cleanPattern(draft)},null,2)],{type:'application/json'}),filename()+'.json');});
$('#importJson').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>500000)throw Error('File JSON terlalu besar (maksimal 500 KB).');const data=JSON.parse(await file.text()),p=cleanPattern(data.pattern);loadDraft(p);if(Number.isFinite(+data.bpm))$('#bpm').value=Math.max(30,Math.min(180,+data.bpm));activateDraft();status('#editorStatus','JSON diimpor dan siap dimainkan. Simpan untuk memasukkannya ke koleksi.');}catch(err){status('#editorStatus','Impor gagal: '+err.message,true);}e.target.value='';});


$('#exportMidi').addEventListener('click',()=>{syncDraftName();download(new Blob([createMidi(cleanPattern(draft),bpm())],{type:'audio/midi'}),filename()+'.mid');});

// Search local patterns; external searches are explicit links, never fake results.
function makeLink(text,url){const a=document.createElement('a');a.textContent=text;a.href=url;a.target='_blank';a.rel='noopener noreferrer';return a;}
function renderLibrary(){const q=$('#songSearch').value.trim().toLocaleLowerCase('id'),host=$('#libraryResults');host.replaceChildren();const matches=Object.entries(patterns).filter(([key,p])=>key!=='draft'&&(p.name+' '+(p.source||'')).toLocaleLowerCase('id').includes(q));for(const [key,p]of matches.slice(0,30)){const card=document.createElement('div');card.className='result-card';const meta=document.createElement('div'),h=document.createElement('h4'),desc=document.createElement('p');h.textContent=p.name;desc.textContent=(key.startsWith('saved_')?'Koleksi kamu':'Latihan bawaan')+' · '+p.meter+' · '+(p.steps/(p.barSteps||p.perBeat*(p.meter==='6/8'?2:Number(p.meter.split('/')[0])))).toFixed(0)+' bar';meta.append(h,desc);const b=document.createElement('button');b.textContent='Mainkan';b.addEventListener('click',()=>{const saved=appData.patterns.find(item=>'saved_'+item.id===key);if(saved)$('#bpm').value=saved.bpm;choose(key);play();});card.append(meta,b);host.append(card);}if(!matches.length){const p=document.createElement('p');p.className='library-empty';p.textContent='Belum ada pola lokal dengan judul itu. Cari partitur lewat tautan berikut, atau buat pola dan simpan dengan judul lagu.';host.append(p);}const links=$('#webSearch');links.replaceChildren();if(q){const phrase=$('#songSearch').value.trim();links.append(makeLink('Cari partitur drum di web','https://www.google.com/search?q='+encodeURIComponent(phrase+' drum sheet music')),makeLink('Cari di Songsterr','https://www.google.com/search?q='+encodeURIComponent('site:songsterr.com '+phrase+' drums')),makeLink('Cari pelajaran YouTube','https://www.youtube.com/results?search_query='+encodeURIComponent(phrase+' beginner drum lesson')));}const list=$('#savedList');list.replaceChildren();for(const item of appData.patterns){const card=document.createElement('div');card.className='result-card';const label=document.createElement('div');label.textContent=item.pattern.name+' · '+item.bpm+' BPM';const actions=document.createElement('div');actions.className='actions';const edit=document.createElement('button');edit.textContent='Edit salinan';edit.addEventListener('click',()=>{loadDraft(item.pattern);$('#bpm').value=item.bpm;showTool('editor',true);});const remove=document.createElement('button');remove.textContent='Hapus';remove.addEventListener('click',()=>{if(remove.dataset.confirm!=='yes'){remove.dataset.confirm='yes';remove.textContent='Yakin hapus?';return;}const key='saved_'+item.id;if(selected===key)choose('rock');appData.patterns=appData.patterns.filter(x=>x.id!==item.id);delete patterns[key];const option=Array.from($('#pattern').options).find(o=>o.value===key);option?.remove();persist();renderLibrary();});actions.append(edit,remove);card.append(label,actions);list.append(card);}if(!appData.patterns.length)list.textContent='Belum ada koleksi. Simpan hasil editor atau rekaman MIDI untuk mulai.';}
$('#songSearch').addEventListener('input',renderLibrary);

// Web MIDI: only note-on messages with nonzero velocity become strokes.
const gm=MIDI_DRUM_MAP;
let midiAccess=null,midiPort=null,learning=false,totalHits=0,recording=null,recordTimer=null;

function refreshMidi(){const select=$('#midiInput'),prior=select.value;select.replaceChildren();for(const input of midiAccess.inputs.values()){if(input.state==='disconnected')continue;const o=document.createElement('option');o.value=input.id;o.textContent=input.name||'MIDI input';select.append(o);}if(!select.options.length){const o=document.createElement('option');o.value='';o.textContent='Tidak ada perangkat';select.append(o);}if(Array.from(select.options).some(x=>x.value===prior))select.value=prior;attachMidi();}
function attachMidi(){if(midiPort)midiPort.onmidimessage=null;midiPort=midiAccess?.inputs.get($('#midiInput').value)||null;if(midiPort){midiPort.onmidimessage=e=>{const note=parseMidiMessage(e.data);if(note)receiveNote(note.note,note.velocity,performance.now());};status('#midiStatus','Terhubung: '+(midiPort.name||'MIDI input')+'. Pukul pad untuk memeriksa mapping.');}else status('#midiStatus','Tidak ada input aktif. Sambungkan USB MIDI lalu periksa kembali.',true);}
$('#connectMidi').addEventListener('click',async()=>{try{if(!navigator.requestMIDIAccess)throw Error('Web MIDI tidak tersedia di browser ini. Coba Chrome/Edge desktop melalui localhost atau HTTPS.');midiAccess=await navigator.requestMIDIAccess({sysex:false});midiAccess.onstatechange=refreshMidi;refreshMidi();}catch(err){status('#midiStatus','Tidak bisa mengakses MIDI: '+err.message,true);}});
$('#midiInput').addEventListener('change',attachMidi);
$('#learnMidi').addEventListener('click',()=>{learning=true;status('#learnStatus','Pukul pad yang ingin dipetakan ke '+partNames[$('#learnInstrument').value]+'.');});
$('#resetMidiMap').addEventListener('click',()=>{appData.mapping={};persist();learning=false;status('#learnStatus','Mapping kembali ke General MIDI.');});
function receiveNote(note,velocity,time){
 if(learning){appData.mapping[note]=$('#learnInstrument').value;persist();learning=false;status('#learnStatus','Note '+note+' dipetakan ke '+partNames[appData.mapping[note]]+'.');}
 const inst=appData.mapping[note]||gm[note];totalHits++;$('#midiCount').textContent=totalHits+' hit';$('#midiLast').textContent=(partNames[inst]||'Pad belum dipetakan')+' · note '+note+' · velocity '+Math.round(velocity*127);
 if(inst&&$('#midiMonitor').checked){try{initAudio();ctx.resume().catch(()=>{});if(!running)master.gain.value=+$('#volume').value;hit(inst,ctx.currentTime+.005,velocity);}catch{}}
 if(recording&&inst){const t=(time-recording.start)/1000-recording.offset/1000;if(t>=0&&t<recording.duration)recording.hits.push({t,inst,v:velocity,note});}
}

function startRecording(){
 if(recording)return;if(!midiPort&&!$('#keyboardPads').checked){status('#recordStatus','Hubungkan MIDI atau aktifkan pad keyboard untuk mencoba rekaman.',true);return;}
 if(session)finishSession('Sesi diakhiri sebelum merekam.');stop();
 const tempo=bpm(),q=+$('#recordGrid').value,bars=+$('#recordBars').value,now=performance.now(),lead=240000/tempo;
 recording={start:now+lead,duration:240/tempo*bars,tempo,q,bars,hits:[],offset:Math.max(-200,Math.min(200,+$('#inputOffset').value||0)),lastClick:-1};
 $('#recordMidi').disabled=true;$('#stopRecording').disabled=false;for(const id of ['#play','#reset','#pattern','#bpm'])$(id).disabled=true;
 try{initAudio();ctx.resume().catch(()=>{});master.gain.value=+$('#volume').value;}catch{}
 recordTimer=setInterval(()=>{if(!recording)return;const now=performance.now(),elapsed=(now-recording.start)/1000;if(elapsed>=recording.duration){finishRecording();return;}const beat=Math.floor((now-(recording.start-lead))/(60000/tempo));if(beat!==recording.lastClick){recording.lastClick=beat;if(ctx&&$('#click').checked)hit('click',ctx.currentTime+.005,beat%4===0?2:1);}status('#recordStatus',elapsed<0?'Persiapan · '+(Math.floor((elapsed+lead/1000)*tempo/60)%4+1)+' / 4':'Merekam · bar '+(Math.floor(elapsed/(240/tempo))+1)+' / '+bars+' · '+recording.hits.length+' hit');},20);
 status('#recordStatus','Persiapan satu bar. Mulai main setelah empat klik.');
}
function finishRecording(){if(!recording)return;clearInterval(recordTimer);const r=recording;recording=null;$('#recordMidi').disabled=false;$('#stopRecording').disabled=true;for(const id of ['#play','#reset','#pattern','#bpm'])$(id).disabled=false;if(!r.hits.length){status('#recordStatus','Belum ada pukulan dalam rentang rekaman. Tunggu persiapan selesai, lalu pukul pad.',true);return;}const result=quantizeHits(r.hits,r.tempo,r.q,r.bars,'Rekaman MIDI '+new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'}),'MIDI live');loadDraft(result.pattern);$('#bpm').value=r.tempo;activateDraft();showTool('editor',true);status('#editorStatus',r.hits.length+' hit direkam, '+result.dropped+' di luar batas grid. Notasi sudah dibuat. Dengarkan, koreksi, lalu simpan.');status('#recordStatus','Rekaman selesai. Hasil ada di Editor pola.');}
$('#recordMidi').addEventListener('click',startRecording);$('#stopRecording').addEventListener('click',finishRecording);
document.addEventListener('keydown',e=>{if(!$('#keyboardPads').checked||e.repeat||e.altKey||e.ctrlKey||e.metaKey||e.target.isContentEditable||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const notes={KeyA:36,KeyS:38,KeyD:42,KeyJ:48,KeyK:45,KeyL:43,KeyI:51,KeyO:49};if(notes[e.code]){e.preventDefault();receiveNote(notes[e.code],.8,performance.now());}});

// Study links are parsed by host, not by a broad video-ID regex on arbitrary URLs.

let videoId=null,taps=[],tapValue=null;
function loadVideo(segment=false){const id=youtubeId($('#youtubeUrl').value);if(!id){status('#youtubeStatus','Link tidak valid. Gunakan link youtube.com/watch, shorts, atau youtu.be.',true);return;}let a=Math.floor(+$('#ytStart').value||0),b=Math.floor(+$('#ytEnd').value||10);if(segment&&(!(a>=0)||b<=a||b>43200)){status('#youtubeStatus','B harus lebih besar daripada A, maksimum 43.200 detik.',true);return;}videoId=id;const host=$('#youtubeFrame');host.replaceChildren();const frame=document.createElement('iframe');frame.title='Video YouTube untuk belajar drum';frame.allow='accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture';frame.referrerPolicy='strict-origin-when-cross-origin';frame.allowFullscreen=true;frame.src='https://www.youtube-nocookie.com/embed/'+id+'?rel=0&playsinline=1'+(segment?'&start='+a+'&end='+b:'');host.append(frame);host.hidden=false;const links=$('#youtubeExternal');links.replaceChildren(makeLink('Buka video di YouTube','https://www.youtube.com/watch?v='+id+(segment?'&t='+a+'s':'')));status('#youtubeStatus','Video dimuat. Tekan play pada pemutar video. Jika embed diblokir, buka lewat tautan YouTube. Ini mode belajar manual, bukan transkripsi otomatis.');}
$('#loadYoutube').addEventListener('click',()=>loadVideo());$('#applySegment').addEventListener('click',()=>loadVideo(true));
$('#youtubeToDraft').addEventListener('click',()=>{if(!videoId){status('#youtubeStatus','Buka link video dahulu.',true);return;}const p=draftFromUI();p.name='Catatan video '+videoId;p.source='https://www.youtube.com/watch?v='+videoId;loadDraft(p);showTool('editor',true);status('#editorStatus','Draf kosong untuk video '+videoId+'. Isi pukulan yang kamu dengar; ini bukan hasil analisis otomatis.');});

$('#tapTempo').addEventListener('click',()=>{const now=performance.now();if(taps.length&&now-taps[taps.length-1]>2500)taps=[];taps.push(now);taps=taps.slice(-9);tapValue=estimateTap(taps);$('#tapResult').textContent=tapValue?tapValue+' BPM':taps.length+' tap';$('#useTapTempo').disabled=!tapValue;});
$('#useTapTempo').addEventListener('click',()=>{if(tapValue){$('#bpm').value=Math.max(30,Math.min(180,tapValue));status('#youtubeStatus','Tempo player diatur ke '+bpm()+' BPM. Pemutar video tidak berubah kecepatannya.');}});

// Basic spectral-band onset draft. Never described as a faithful song transcription.
let audioPreviewUrl=null;
$('#audioFile').addEventListener('change',()=>{if(audioPreviewUrl)URL.revokeObjectURL(audioPreviewUrl);const f=$('#audioFile').files[0];if(f){audioPreviewUrl=URL.createObjectURL(f);$('#audioPreview').src=audioPreviewUrl;}});

$('#analyzeAudio').addEventListener('click',async()=>{const file=$('#audioFile').files[0];if(!file){status('#audioStatus','Pilih file audio dahulu.',true);return;}if(file.size>30*1024*1024){status('#audioStatus','File melebihi 30 MB. Gunakan rekaman yang lebih pendek.',true);return;}const button=$('#analyzeAudio');button.disabled=true;status('#audioStatus','Membaca audio dan mendeteksi onset…');try{stop();initAudio();const buffer=await ctx.decodeAudioData(await file.arrayBuffer());const start=Math.max(0,+$('#audioStart').value||0);if(start>=buffer.duration)throw Error('Posisi awal melewati akhir audio.');const q=+$('#recordGrid').value,bars=+$('#recordBars').value,tempo=bpm(),duration=Math.min(30,240/tempo*bars,buffer.duration-start),count=Math.floor(duration*buffer.sampleRate),mono=new Float32Array(count);for(let channel=0;channel<buffer.numberOfChannels;channel++){const d=buffer.getChannelData(channel),offset=Math.floor(start*buffer.sampleRate);for(let i=0;i<count;i++)mono[i]+=d[offset+i]/buffer.numberOfChannels;}const hits=detectOnsets(mono,buffer.sampleRate,+$('#audioSensitivity').value,$('#audioMode').value);if(!hits.length)throw Error('Tidak ada onset yang cukup jelas. Coba kepekaan tinggi atau rekaman drum yang lebih bersih.');const result=quantizeHits(hits,tempo,q,bars,file.name.replace(/\.[^.]+$/,'')+' · DRAF AUDIO','Deteksi audio eksperimental');loadDraft(result.pattern);activateDraft();showTool('editor',true);status('#editorStatus','DRAF AUDIO: '+hits.length+' onset perkiraan, '+result.dropped+' di luar grid. BPM '+tempo+'. Dengarkan dan koreksi; ini bukan transkripsi terverifikasi.');status('#audioStatus','Analisis selesai. Draf tersedia di editor.');}catch(err){status('#audioStatus','Analisis gagal: '+err.message,true);}finally{button.disabled=false;}});

// Session timer and a small, honest practice journal.
let session=null,sessionTimer=null;
function paintSession(){if(!session)return;const remaining=Math.max(0,Math.ceil((session.end-Date.now())/1000));$('#sessionClock').textContent=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');if(!remaining)finishSession('Sesi selesai. Bagus, istirahat sebentar sebelum lanjut.');}
function finishSession(message){if(!session)return;const seconds=Math.max(0,Math.min(session.minutes*60,Math.round((Date.now()-session.start)/1000)));if(seconds>=5){appData.sessions.unshift({name:session.name,bpm:session.bpm,seconds,date:Date.now()});appData.sessions=appData.sessions.slice(0,100);persist();}session=null;clearInterval(sessionTimer);stop();$('#startSession').disabled=false;$('#endSession').disabled=true;status('#sessionStatus',message||'Sesi diakhiri. Sesi minimal 5 detik dicatat di jurnal.');renderHistory();}
function renderHistory(){const host=$('#sessionHistory');host.replaceChildren();for(const entry of appData.sessions.slice(0,15)){const p=document.createElement('p');p.textContent=new Date(entry.date).toLocaleDateString('id-ID')+' · '+entry.name+' · '+entry.bpm+' BPM · '+Math.floor(entry.seconds/60)+'m '+entry.seconds%60+'d';host.append(p);}if(!appData.sessions.length)host.textContent='Belum ada sesi tercatat.';}
$('#startSession').addEventListener('click',()=>{if(recording){status('#sessionStatus','Selesaikan rekaman MIDI sebelum memulai sesi.',true);return;}if(session)return;const minutes=Math.max(1,Math.min(60,+$('#sessionMinutes').value||5));session={start:Date.now(),end:Date.now()+minutes*60000,minutes,name:patterns[selected].name,bpm:bpm()};$('#startSession').disabled=true;$('#endSession').disabled=false;if(!running)play();status('#sessionStatus','Sesi berjalan. Timer mengukur waktu sesi, termasuk saat kamu menjeda atau membaca.');sessionTimer=setInterval(paintSession,500);paintSession();});
$('#endSession').addEventListener('click',()=>finishSession());document.querySelectorAll('[data-session-pattern]').forEach(b=>b.addEventListener('click',()=>{if(session){status('#sessionStatus','Akhiri sesi yang sedang berjalan sebelum mengganti target.',true);return;}choose(b.dataset.sessionPattern);$('#sessionMinutes').value=b.dataset.sessionMinutes;$('#sessionClock').textContent=String(b.dataset.sessionMinutes).padStart(2,'0')+':00';}));
window.addEventListener('beforeunload',()=>{if(midiPort)midiPort.onmidimessage=null;if(audioPreviewUrl)URL.revokeObjectURL(audioPreviewUrl);});
loadApp();for(const item of appData.patterns)installPattern('saved_'+item.id,item.pattern);drawEditor();renderLibrary();renderHistory();render();
if(!storageOK)status('#editorStatus','Penyimpanan browser tidak tersedia atau data lama tidak terbaca. Gunakan ekspor JSON untuk cadangan.',true);

